class Solution {
public:
    vector<int> maxSubsequence(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> idx(n);
        for (int i = 0; i < n; i++) idx[i] = i;
        nth_element(idx.begin(), idx.begin() + k, idx.end(),
            [&](int a, int b) { return nums[a] > nums[b]; });
        vector<char> mark(n, 0);
        for (int i = 0; i < k; i++) mark[idx[i]] = 1;
        vector<int> res;
        res.reserve(k);
        for (int i = 0; i < n; i++) if (mark[i]) res.push_back(nums[i]);
        return res;
    }
};
